export function LoginPage() {
  const navigate = useNavigate();
  const [showRegister, setShowRegister] = useState(false);
  const [registerRole, setRegisterRole] = useState<Role | null>(null);
  const [showLogin, setShowLogin] = useState(false);
  const [dark, setDark] = useState(false);
  const [largeText, setLargeText] = useState(false);
  const [highContrast, setHighContrast] = useState(false);
  useEffect(() => {
    const root = document.documentElement;
    root.classList.toggle("dark", dark);
    root.classList.toggle("large-text", largeText);
    root.classList.toggle("high-contrast", highContrast);
  }, [dark, largeText, highContrast]);
  const [busy, setBusy] = useState(false);
  const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); const email = String(f.get("email") ?? "").trim().toLowerCase(); const password = String(f.get("password") ?? ""); if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) { toast.error("Informe um e-mail válido."); return; } setBusy(true); const { error } = await supabase.auth.signInWithPassword({ email, password }); setBusy(false); if (error) { toast.error(error.message.includes("confirm") ? "Confirme seu e-mail antes de entrar." : "E-mail ou senha incorretos."); return; } navigate({ to: "/dashboard" }); };
  const google = async () => { const r = await lovable.auth.signInWithOAuth("google", { redirect_uri: window.location.origin }); if (r.error) { toast.error("Não foi possível entrar com Google."); return; } if (r.redirected) return; navigate({ to: "/dashboard" }); };
  const forgot = async () => { const email = (document.querySelector('input[name="email"]') as HTMLInputElement | null)?.value.trim(); if (!email) { toast.error("Digite seu e-mail no campo acima."); return; } await supabase.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}/reset-password` }); toast.success("Se o e-mail existir, enviaremos um link de redefinição."); };
  useEffect(() => { supabase.auth.getSession().then(({ data }) => { if (data.session) navigate({ to: "/dashboard" }); }); }, [navigate]);
  return <main className="min-h-dvh bg-background">
    <header className="absolute inset-x-0 top-0 z-30">
      <div className="mx-auto flex max-w-[1440px] items-center justify-between px-5 py-5 sm:px-8 lg:px-12">
        <Brand />
        <div className="flex items-center gap-2">
          <Button variant="outline" size="icon" className="min-h-11 min-w-11 bg-background/90" onClick={() => setDark(value => !value)} aria-label={dark ? "Ativar tema claro" : "Ativar tema escuro"} title={dark ? "Tema claro" : "Tema escuro"}>{dark ? <Sun /> : <Moon />}</Button>
          <DropdownMenu>
            <DropdownMenuTrigger asChild><Button variant="outline" size="icon" className="min-h-11 min-w-11 bg-background/90" aria-label="Opções de acessibilidade"><Accessibility /></Button></DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-64">
              <DropdownMenuLabel>Acessibilidade</DropdownMenuLabel>
              <DropdownMenuItem onClick={() => setLargeText(value => !value)}><Type /> Texto ampliado <span className="ml-auto font-bold">{largeText ? "Ativo" : "Inativo"}</span></DropdownMenuItem>
              <DropdownMenuItem onClick={() => setHighContrast(value => !value)}><Contrast /> Alto contraste <span className="ml-auto font-bold">{highContrast ? "Ativo" : "Inativo"}</span></DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
    </header>

    <section className="flex min-h-[92dvh] items-center px-5 pb-12 pt-28 sm:px-8 lg:px-12">
      <div className="mx-auto grid w-full max-w-[1440px] items-center gap-10 lg:grid-cols-12 lg:gap-14">
        <div className="order-2 lg:order-1 lg:col-span-7">
          <div className="hero-image-frame relative overflow-hidden rounded-3xl border-4 border-card bg-card shadow-2xl">
            <img src={communityImage.url} alt="Estudantes, professores e voluntários reunidos sobre uma ponte feita de livros coloridos" className="aspect-[4/3] w-full object-cover" width={960} height={768} />
            <div className="absolute bottom-4 left-4 flex flex-wrap gap-2 sm:bottom-6 sm:left-6"><Badge className="bg-success text-success-foreground">Aprender</Badge><Badge className="bg-coral text-coral-foreground">Ensinar</Badge><Badge className="bg-warning text-warning-foreground">Transformar</Badge></div>
          </div>
        </div>

        <div className="order-1 page-enter lg:order-2 lg:col-span-5">
          <Badge variant="secondary" className="mb-5 gap-2 px-3 py-2"><Sparkles className="size-4 text-coral" /> Educação pública conectada</Badge>
          <h1 className="font-display text-5xl font-black leading-[.95] sm:text-6xl lg:text-7xl">Vamos aprender <span className="text-primary">juntos?</span></h1>
          <div className="mt-6 h-2 w-20 rounded-full bg-coral" />
          <p className="mt-6 max-w-xl text-lg leading-relaxed text-muted-foreground sm:text-xl">A Ponte 404 conecta alunos de escolas públicas a professores e voluntários para transformar dúvidas em caminhos e conhecimento em oportunidades.</p>
          <div className="mt-8 flex flex-col gap-3 sm:flex-row lg:flex-col xl:flex-row">
            <Button size="lg" className="h-14 px-8 text-base shadow-lg" onClick={() => setShowLogin(true)}>Entrar na plataforma <ArrowRight /></Button>
            <Dialog open={showRegister} onOpenChange={open => { setShowRegister(open); if (!open) setRegisterRole(null); }}><DialogTrigger asChild><Button size="lg" variant="outline" className="h-14 bg-card px-8 text-base">Criar conta</Button></DialogTrigger><DialogContent><RegisterFlow initialRole={registerRole} close={() => setShowRegister(false)} /></DialogContent></Dialog>
          </div>
          <div className="mt-8 flex items-center gap-3 text-sm text-muted-foreground"><span className="grid size-10 place-items-center rounded-full bg-success/15 text-success"><ShieldCheck className="size-5" /></span><span><b className="block text-foreground">Um espaço seguro e inclusivo</b>Perfis validados e caminhos para todos.</span></div>
        </div>
      </div>
    </section>

    <section className="border-y bg-card px-5 py-8 sm:px-8" aria-labelledby="journeys-title">
      <div className="mx-auto max-w-[1200px]"><h2 id="journeys-title" className="sr-only">Escolha sua jornada</h2><div className="grid gap-4 sm:grid-cols-3">{([
        [GraduationCap, "Sou aluno", "Quero aprender e encontrar apoio", "bg-info text-info-foreground"],
        [BookOpen, "Sou professor", "Quero criar cursos e ensinar", "bg-success/15 text-success"],
        [HeartHandshake, "Sou voluntário", "Quero ensinar e também aprender", "bg-accent text-accent-foreground"],
      ] as const).map(([Icon, title, text, tone], index) => <button key={title} type="button" onClick={() => { setRegisterRole((['Aluno','Professor','Voluntário'] as Role[])[index] ?? null); setShowRegister(true); }} className="lift-card flex min-h-24 items-center gap-4 rounded-xl border bg-background p-4 text-left focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"><span className={`grid size-12 shrink-0 place-items-center rounded-xl ${tone}`}><Icon /></span><span><b className="block font-display text-lg">{title}</b><span className="text-sm text-muted-foreground">{text}</span></span><ChevronRight className="ml-auto size-5 text-muted-foreground" /></button>)}</div></div>
    </section>

    <Dialog open={showLogin} onOpenChange={setShowLogin}><DialogContent><DialogHeader><DialogTitle className="text-2xl">Que bom ter você aqui.</DialogTitle><DialogDescription>Entre para continuar aprendendo, ensinando e transformando.</DialogDescription></DialogHeader><form onSubmit={submit} className="space-y-5"><Button type="button" variant="outline" className="h-12 w-full" onClick={google}>Continuar com Google</Button><Field label="E-mail"><Input name="email" type="email" autoComplete="email" placeholder="voce@email.com" className="h-12" required /></Field><Field label="Senha"><Input name="password" type="password" autoComplete="current-password" placeholder="Sua senha" className="h-12" required /></Field><div className="flex flex-wrap items-center justify-between gap-3 text-sm"><label className="flex min-h-11 items-center gap-2"><input type="checkbox" className="size-4 accent-primary" /> Lembrar de mim</label><Button type="button" variant="link" className="px-0" onClick={forgot}>Esqueci minha senha</Button></div><Button disabled={busy} className="h-12 w-full text-base">{busy ? "Entrando…" : "Entrar"} <ArrowRight /></Button><div className="flex items-center justify-center gap-2 text-xs text-muted-foreground"><ShieldCheck className="size-4 text-success" /> Seus dados estão protegidos.</div></form></DialogContent></Dialog>
  </main>;
}

function RegisterFlow({ close, initialRole = null }: { close: () => void; initialRole?: Role | null }) {
  const [role, setRole] = useState<Role | null>(initialRole); const [fileName,setFileName]=useState(""); const [busy,setBusy]=useState(false); const navigate = useNavigate();
  if (!role) return <><DialogHeader><DialogTitle className="text-2xl">Como você quer fazer parte?</DialogTitle><DialogDescription>Uma conta, o perfil certo para sua jornada.</DialogDescription></DialogHeader><div className="grid gap-3 sm:grid-cols-3">{([
    ["Aluno", GraduationCap, "Quero aprender"], ["Professor", BookOpen, "Tenho formação"], ["Voluntário", HeartHandshake, "Quero compartilhar"],
  ] as const).map(([r, Icon, text]) => <button key={r} onClick={() => setRole(r)} className="lift-card rounded-xl border bg-card p-5 text-left"><Icon className="mb-5 size-8 text-primary" /><strong className="block font-display">{r}</strong><span className="text-xs text-muted-foreground">{text}</span></button>)}</div></>;
  return <form onSubmit={async e => { e.preventDefault(); if (role !== "Aluno" && !fileName) { toast.error("Anexe o documento solicitado."); return; } const f = new FormData(e.currentTarget); const name = String(f.get("name") ?? "").trim(); const email = String(f.get("email") ?? "").trim().toLowerCase(); const password = String(f.get("password") ?? ""); if (password.length < 8 || !/[0-9]/.test(password) || !/[a-zA-Z]/.test(password)) { toast.error("A senha precisa de 8+ caracteres com letras e números."); return; } const subjects = String(f.get("subjects") ?? "").split(",").map(x => x.trim()).filter(Boolean); setBusy(true); const { data, error } = await supabase.auth.signUp({ email, password, options: { emailRedirectTo: `${window.location.origin}/dashboard`, data: { display_name: name, role: role === "Professor" ? "professor" : role === "Voluntário" ? "voluntario" : "aluno", grade: role === "Aluno" ? String(f.get("subjects") ?? "") : null, subjects: role === "Aluno" ? [] : subjects, document_name: fileName || null } } }); setBusy(false); if (error) { toast.error(error.message.toLowerCase().includes("registered") ? "Este e-mail já tem conta. Entre com sua senha." : (error.message.toLowerCase().includes("not allowed") ? "Esse e-mail não pode receber mensagens. Use um e-mail real." : error.message.toLowerCase().includes("weak") || error.message.toLowerCase().includes("guess") ? "Essa senha é muito comum. Escolha outra mais difícil de adivinhar." : "Não foi possível criar a conta: " + error.message)); return; } if (data.user && data.user.identities?.length === 0) { toast.error("Este e-mail já tem conta. Entre com sua senha."); return; } close(); if (data.session) { navigate({ to: "/dashboard" }); } else { toast.success("Conta criada! Enviamos um link de confirmação para seu e-mail."); } }}><DialogHeader><DialogTitle>Cadastro de {role}</DialogTitle><DialogDescription>{role === "Voluntário" ? "Você terá os modos Ensinar e Aprender na mesma conta." : "Complete seus dados para criar sua conta."}</DialogDescription></DialogHeader><div className="mt-4 grid gap-4 sm:grid-cols-2"><Field label="Nome completo"><Input name="name" autoComplete="name" placeholder="Seu nome" minLength={3} maxLength={100} required /></Field><Field label="E-mail"><Input name="email" type="email" autoComplete="email" placeholder="voce@email.com" maxLength={255} required /></Field><Field label="Senha"><Input name="password" type="password" autoComplete="new-password" placeholder="8+ caracteres, letras e números" minLength={8} required /></Field><Field label={role === "Aluno" ? "Série escolar" : "Disciplinas (vírgula)"}><Input name="subjects" placeholder={role === "Aluno" ? "Ex.: 2º ano" : "Ex.: Matemática"} maxLength={100} required /></Field><Field label="Horários disponíveis"><Input placeholder="Ex.: terças à tarde" maxLength={100} required /></Field>{role !== "Aluno" && <div className="sm:col-span-2"><label className="flex min-h-24 cursor-pointer items-center justify-center gap-3 rounded-xl border border-dashed border-primary/40 bg-secondary px-4 text-center text-sm font-bold text-primary"><UploadCloud /> {fileName || `Enviar ${role === "Professor" ? "diploma ou certificado" : "comprovante de escolaridade"}`}<input type="file" accept=".pdf,.jpg,.jpeg,.png" className="sr-only" onChange={e => { const file=e.target.files?.[0]; if (file && file.size > 5_000_000) { toast.error("O arquivo deve ter até 5 MB."); e.target.value=""; return; } setFileName(file?.name ?? ""); if(file) toast.success("Documento anexado!"); }} /></label></div>}{role === "Voluntário" && <div className="sm:col-span-2"><Field label="O que também quer aprender? (opcional)"><Input placeholder="Ex.: Inglês e programação" maxLength={100} /></Field></div>}</div><div className="mt-5 flex justify-between"><Button type="button" variant="ghost" onClick={() => setRole(null)}>Voltar</Button><Button type="submit" disabled={busy}>{busy ? "Criando…" : "Criar conta"} <Check /></Button></div></form>;
}

function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="grid gap-2 text-sm font-bold">{label}{children}</label>; }


function SideLink({ to, label, icon: Icon, active }: { to: string; label: string; icon: typeof Home; active: boolean }) { return <Link to={to} className={`flex h-11 items-center gap-3 rounded-xl px-3 text-sm font-bold transition-colors ${active ? "bg-primary text-primary-foreground shadow-md" : "text-muted-foreground hover:bg-muted hover:text-foreground"}`}><Icon className="size-5" />{label}</Link>; }
function Avatar({ initials, className = "" }: { initials: string; className?: string }) { return <span className={`grid size-10 shrink-0 place-items-center rounded-xl bg-primary font-display text-sm font-black text-primary-foreground ${className}`}>{initials}</span>; }
function PageTitle({ eyebrow, title, text, action }: { eyebrow?: string; title: string; text: string; action?: ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div>{eyebrow && <div className="mb-2 text-xs font-extrabold uppercase text-primary">{eyebrow}</div>}<h1 className="font-display text-3xl font-black sm:text-4xl">{title}</h1><p className="mt-1 text-muted-foreground">{text}</p></div>{action}</div>; }
function Stat({ icon: Icon, label, value, helper, tone = "text-primary bg-secondary" }: { icon: typeof Home; label: string; value: string; helper: string; tone?: string }) { return <Card className="lift-card"><CardContent className="p-5"><div className={`mb-4 grid size-10 place-items-center rounded-xl ${tone}`}><Icon /></div><div className="font-display text-3xl font-black">{value}</div><div className="text-sm font-bold">{label}</div><div className="mt-1 text-xs text-muted-foreground">{helper}</div></CardContent></Card>; }
function TrustBadge({ role }: { role: Instructor["role"] }) { return role === "Professor" ? <Badge className="gap-1 bg-success text-success-foreground"><CheckCircle2 className="size-3" /> Certificado validado</Badge> : <Badge className="gap-1 bg-coral text-coral-foreground"><ShieldCheck className="size-3" /> Escolaridade validada</Badge>; }

export function DashboardPage() { const userName=useUserName(); const [details,setDetails]=useState(false); return <AppShell><div className="page-enter"><PageTitle eyebrow="Quinta-feira, 17 de setembro" title={`Olá, ${userName.split(" ")[0]}! 👋`} text="Seu próximo passo está logo ali. Vamos aprender?" action={<Button asChild><Link to="/busca"><Search /> Encontrar instrutor</Link></Button>} /><section className="relative mb-7 overflow-hidden rounded-2xl bridge-gradient p-6 text-primary-foreground shadow-xl sm:p-8"><div className="relative z-10 max-w-2xl"><Badge className="mb-4 bg-background/20 text-primary-foreground">Próxima aula • hoje</Badge><h2 className="text-2xl font-black sm:text-3xl">Funções do 2º grau, sem mistério.</h2><p className="mt-2 text-primary-foreground/80">Com Marina Souza às 19:00 • Sala virtual</p><div className="mt-6 flex flex-wrap gap-3"><Button className="bg-background text-primary hover:bg-background/90" onClick={()=>toast.success("Sala virtual aberta! Prepare seu caderno.")}><PlayCircle /> Entrar na aula</Button><Button variant="outline" className="border-primary-foreground/30 bg-transparent text-primary-foreground hover:bg-primary-foreground/10" onClick={()=>setDetails(true)}>Ver detalhes</Button></div></div><div className="absolute -bottom-10 right-10 hidden text-[150px] font-black text-primary-foreground/10 md:block">∑</div></section><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat icon={CalendarDays} value="04" label="Aulas este mês" helper="2 ainda esta semana" /><Stat icon={BookMarked} value="03" label="Cursos em andamento" helper="68% de progresso médio" tone="bg-accent text-accent-foreground" /><Stat icon={Clock3} value="18h" label="Tempo aprendendo" helper="+4h em setembro" tone="bg-success/15 text-success" /><Stat icon={Star} value="4,9" label="Sua média" helper="12 avaliações recebidas" tone="bg-warning/25 text-warning-foreground" /></div><div className="mt-7 grid gap-7 xl:grid-cols-[1.35fr_.65fr]"><section><SectionHead title="Continue aprendendo" link="/cursos" /> <div className="grid gap-4 sm:grid-cols-2">{courses.slice(0,2).map(c=><button key={c.title} className="text-left" onClick={()=>toast.info(`Abrindo ${c.title}.`)}>{CourseCard(c)}</button>)}</div></section><section><SectionHead title="Próximas aulas" link="/aulas" /><Card><CardContent className="divide-y p-0">{([ ["19:00","Matemática","Hoje","Marina"], ["16:30","Redação","Amanhã","Lívia"], ["10:00","Inglês","Sábado","Rafael"] ] as [string,string,string,string][]).map(x => <button key={x[0]+x[1]} className="flex w-full items-center gap-3 p-4 text-left hover:bg-muted/60" onClick={()=>setDetails(true)}><div className="rounded-lg bg-secondary px-3 py-2 text-center"><b className="block text-sm">{x[0]}</b><span className="text-[10px] text-muted-foreground">{x[2]}</span></div><div className="min-w-0 flex-1"><b className="block truncate text-sm">{x[1]}</b><span className="text-xs text-muted-foreground">com {x[3]}</span></div><ChevronRight className="size-4 text-muted-foreground" /></button>)}</CardContent></Card></section></div><section className="mt-7"><SectionHead title="Gente boa para conhecer" link="/busca" /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{instructors.slice(0,3).map(p=><InstructorCard key={p.name} {...p}/>)}</div></section></div><Dialog open={details} onOpenChange={setDetails}><DialogContent><DialogHeader><DialogTitle>Funções do 2º grau</DialogTitle><DialogDescription>Hoje, 19:00–20:00 • Marina Souza • Sala virtual</DialogDescription></DialogHeader><div className="rounded-xl bg-muted p-4 text-sm">Revise parábolas, raízes e resolução de exercícios. Tenha papel, lápis e calculadora por perto.</div><Button onClick={()=>{setDetails(false);toast.success("Lembrete ativado para 15 minutos antes.");}}><Bell/> Ativar lembrete</Button></DialogContent></Dialog></AppShell>; }

function SectionHead({ title, link }: { title: string; link: string }) { return <div className="mb-4 flex items-center justify-between"><h2 className="text-xl font-black">{title}</h2><Link to={link} className="flex items-center gap-1 text-sm font-bold text-primary">Ver todos <ChevronRight className="size-4" /></Link></div>; }
function CourseCard(c: typeof courses[number]) { return <Card key={c.title} className="lift-card overflow-hidden"><CardContent className="p-5"><div className={`mb-5 grid size-12 place-items-center rounded-xl font-black ${c.color}`}>{c.icon}</div><Badge variant="secondary">{c.subject}</Badge><h3 className="mt-3 text-lg font-black">{c.title}</h3><p className="mt-1 text-sm text-muted-foreground">com {c.teacher} • {c.lessons} aulas</p><div className="mt-5 flex items-center gap-3"><div className="h-2 flex-1 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bridge-gradient" style={{ width: `${Math.max(c.progress, 6)}%` }} /></div><span className="text-xs font-black">{c.progress}%</span></div></CardContent></Card>; }
function InstructorCard(p: Instructor) { const [requested,setRequested]=useState(false); const [profile,setProfile]=useState(false); return <Card key={p.name} className="lift-card"><CardContent className="p-5"><div className="flex items-start gap-4"><Avatar initials={p.initials} className={p.tone} /><div className="min-w-0 flex-1"><h3 className="font-black">{p.name}</h3><p className="text-sm text-muted-foreground">{p.subject}</p></div><DropdownMenu><DropdownMenuTrigger asChild><Button size="icon" variant="ghost" aria-label={`Opções de ${p.name}`}><MoreHorizontal /></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem onClick={()=>setProfile(true)}><User/> Ver perfil</DropdownMenuItem><DropdownMenuItem onClick={()=>toast.success("Link do perfil copiado.")}><ArrowRight/> Compartilhar</DropdownMenuItem><DropdownMenuItem onClick={()=>toast.info("Denúncia registrada para análise.")}><ShieldCheck/> Denunciar</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div><div className="mt-4"><TrustBadge role={p.role} /></div><div className="mt-5 flex items-center justify-between border-t pt-4 text-sm"><span className="flex items-center gap-1 font-black"><Star className="size-4 fill-warning text-warning" /> {p.rating}</span><span className="text-muted-foreground">{p.lessons} aulas</span><Button size="sm" variant={requested?"secondary":"outline"} disabled={requested} onClick={() => {setRequested(true);toast.success(`Solicitação enviada para ${p.name}!`);}}>{requested?"Enviada":"Solicitar"}</Button></div></CardContent><Dialog open={profile} onOpenChange={setProfile}><DialogContent><DialogHeader><DialogTitle>{p.name}</DialogTitle><DialogDescription>{p.role} de {p.subject}</DialogDescription></DialogHeader><div className="flex items-center gap-4 rounded-xl bg-muted p-5"><Avatar initials={p.initials} className={p.tone}/><div><TrustBadge role={p.role}/><p className="mt-2 text-sm text-muted-foreground">{p.rating} de avaliação em {p.lessons} aulas realizadas.</p></div></div><Button onClick={()=>{setRequested(true);setProfile(false);toast.success(`Solicitação enviada para ${p.name}!`);}}>Solicitar aula</Button></DialogContent></Dialog></Card>; }

export function LessonsPage() { const initial=[{subject:"Matemática",title:"Funções do 2º grau",when:"Hoje, 19:00",teacher:"Marina Souza",status:"Confirmada",topics:["Revisão: o que é uma função","Gráfico da parábola e concavidade","Raízes e vértice na prática","Exercícios guiados com correção"]},{subject:"Português",title:"Estrutura da redação",when:"Amanhã, 16:30",teacher:"Lívia Santos",status:"Aguardando",topics:["Introdução que prende atenção","Desenvolvimento com argumentos","Conclusão e proposta de intervenção","Erros mais comuns do Enem"]},{subject:"Inglês",title:"Conversação básica",when:"Sáb, 10:00",teacher:"Rafael Lima",status:"Confirmada",topics:["Cumprimentos e apresentações","Perguntas do dia a dia","Pronúncia de palavras-chave","Prática em duplas"]}]; const [doneTopics,setDoneTopics]=useState<string[]>([]); const toggleTopic=(t:string)=>setDoneTopics(v=>v.includes(t)?v.filter(x=>x!==t):[...v,t]); const [tab,setTab]=useState("Agendadas"); const [items,setItems]=useState(initial); const [request,setRequest]=useState(false); const [detail,setDetail]=useState<typeof initial[number]|null>(null); return <AppShell><div className="page-enter"><PageTitle eyebrow="Sua agenda" title="Aulas" text="Organize seus encontros e acompanhe sua evolução." action={<LessonAction onRequest={() => setRequest(true)} onCreated={l=>setItems(v=>[l,...v])} />} /><Tabs values={["Agendadas","Em andamento","Concluídas"]} value={tab} setValue={setTab} /><div className="mt-6 space-y-4">{tab === "Agendadas" ? items.map((x,i) => <Card key={x.title} className="lift-card"><CardContent className="flex flex-col gap-5 p-5 sm:flex-row sm:items-center"><div className={`grid size-14 shrink-0 place-items-center rounded-xl text-xl font-black ${i===0?"bg-info text-info-foreground":i===1?"bg-success/15 text-success":"bg-accent text-accent-foreground"}`}>{i===0?"∑":i===1?"Aa":"Hi"}</div><div className="flex-1"><div className="mb-1 flex flex-wrap items-center gap-2"><Badge variant="secondary">{x.subject}</Badge><Badge className={x.status === "Confirmada" ? "bg-success text-success-foreground" : "bg-warning text-warning-foreground"}>{x.status}</Badge></div><h3 className="text-lg font-black">{x.title}</h3><p className="mt-1 text-sm text-muted-foreground"><Clock3 className="mr-1 inline size-4" />{x.when} • com {x.teacher}</p></div><div className="flex gap-2"><Button variant="outline" onClick={() => {setItems(v=>v.filter(a=>a.title!==x.title));toast.info("Aula cancelada.");}}>Cancelar</Button>{x.status==="Aguardando"&&<Button variant="secondary" onClick={()=>{setItems(v=>v.map(a=>a.title===x.title?{...a,status:"Confirmada"}:a));toast.success("Aula confirmada!");}}>Confirmar</Button>}<Button onClick={()=>setDetail(x)}>Detalhes</Button></div></CardContent></Card>) : tab === "Em andamento" ? <EmptyState icon={PlayCircle} title="Nenhuma aula acontecendo agora" text="Quando uma sala estiver aberta, ela aparecerá aqui." /> : <Card><CardContent className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center"><ClipboardCheck className="size-10 text-success"/><div className="flex-1"><b>Introdução à lógica</b><p className="text-sm text-muted-foreground">Concluída em 12 de setembro • Caio Mendes</p></div><Button onClick={()=>toast.success("Avaliação de 5 estrelas enviada!")}><Star/> Avaliar aula</Button></CardContent></Card>}</div></div><Dialog open={request} onOpenChange={setRequest}><DialogContent><DialogHeader><DialogTitle>Solicitar uma aula</DialogTitle><DialogDescription>Escolha o assunto e o melhor horário.</DialogDescription></DialogHeader><form className="space-y-4" onSubmit={e=>{e.preventDefault();setRequest(false);toast.success("Solicitação enviada aos instrutores disponíveis!");}}><Field label="Assunto"><Input required maxLength={100} placeholder="Ex.: equações do 2º grau"/></Field><Field label="Data e horário"><Input type="datetime-local" required/></Field><Button className="w-full">Enviar solicitação</Button></form></DialogContent></Dialog><Dialog open={Boolean(detail)} onOpenChange={open=>{if(!open)setDetail(null)}}><DialogContent><DialogHeader><DialogTitle>{detail?.title}</DialogTitle><DialogDescription>{detail?.when} • {detail?.teacher} • Sala virtual</DialogDescription></DialogHeader>{detail&&<div><div className="mb-2 flex items-center justify-between text-sm"><b>Temas da aula</b><span className="text-muted-foreground">{detail.topics.filter(t=>doneTopics.includes(t)).length}/{detail.topics.length} vistos</span></div><div className="space-y-2">{detail.topics.map((t,ti)=>{const done=doneTopics.includes(t);return <button key={t} onClick={()=>toggleTopic(t)} className={`flex w-full items-center gap-3 rounded-xl border p-3 text-left text-sm transition-colors ${done?"border-success/40 bg-success/10":"hover:bg-muted/60"}`}><span className={`grid size-6 shrink-0 place-items-center rounded-full text-xs font-black ${done?"bg-success text-success-foreground":"bg-muted text-muted-foreground"}`}>{done?"✓":ti+1}</span><span className={done?"text-muted-foreground line-through":""}>{t}</span></button>})}</div><div className="mt-4 flex flex-wrap gap-2"><Button onClick={()=>{setDetail(null);toast.success("Sala virtual aberta! Bons estudos.");}}><PlayCircle/> Entrar na sala</Button><Button variant="outline" onClick={()=>toast.success("Lembrete ativado!")}><Bell/> Ativar lembrete</Button></div></div>}</DialogContent></Dialog></AppShell>; }

export function CoursesPage() { const all=[...courses,{title:"Física do cotidiano",subject:"Física",teacher:"João Vitor",progress:0,lessons:8,icon:"⚛",color:"bg-info text-info-foreground"},{title:"Inglês para o mundo",subject:"Inglês",teacher:"Rafael Lima",progress:0,lessons:10,icon:"Hi",color:"bg-accent text-accent-foreground"},{title:"Biologia em mapas",subject:"Biologia",teacher:"Beatriz Costa",progress:15,lessons:9,icon:"DNA",color:"bg-success/15 text-success"}]; const [category,setCategory]=useState("Todos"); const [enrolled,setEnrolled]=useState<string[]>(courses.filter(c=>c.progress>0).map(c=>c.title)); const matches=(c:typeof courses[number])=>category==="Todos"||c.subject===category||(category==="Linguagens"&&["Português","Inglês"].includes(c.subject))||(category==="Ciências"&&["Física","Biologia"].includes(c.subject)); return <AppShell><div className="page-enter"><PageTitle eyebrow="Trilhas de conhecimento" title="Cursos" text="Aprenda no seu ritmo, aula após aula." /><div className="mb-6 flex gap-3 overflow-x-auto pb-2">{["Todos","Matemática","Linguagens","Tecnologia","Ciências"].map(x=><Button key={x} variant={category===x?"default":"outline"} size="sm" onClick={()=>setCategory(x)}>{x}</Button>)}</div><div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{all.filter(matches).map(c=><Dialog key={c.title}><DialogTrigger asChild><button className="text-left">{CourseCard(c)}</button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>{c.title}</DialogTitle><DialogDescription>Uma trilha prática de {c.lessons} aulas com {c.teacher}.</DialogDescription></DialogHeader><div className="rounded-xl bg-muted p-5"><b>O que você vai aprender</b><ul className="mt-3 space-y-2 text-sm text-muted-foreground"><li>• Fundamentos essenciais do tema</li><li>• Exercícios guiados e exemplos reais</li><li>• Projeto de conclusão com acompanhamento</li></ul></div><Button onClick={() => {if(!enrolled.includes(c.title))setEnrolled(v=>[...v,c.title]);toast.success(enrolled.includes(c.title)?"Continuando de onde você parou.":"Inscrição confirmada!");}}>{enrolled.includes(c.title)?<><PlayCircle/>Continuar curso</>:"Inscrever-se gratuitamente"}</Button></DialogContent></Dialog>)}</div></div></AppShell>; }

export function SearchPage() { const [query,setQuery]=useState(""); const [role,setRole]=useState("Todos"); const [filters,setFilters]=useState(false); const [rating,setRating]=useState(0); const [period,setPeriod]=useState("Qualquer horário"); const filtered=useMemo(()=>instructors.filter(i=>(role==="Todos"||i.role===role)&&i.rating>=rating&&(`${i.name} ${i.subject}`.toLowerCase().includes(query.trim().toLowerCase()))),[query,role,rating]); return <AppShell><div className="page-enter"><PageTitle eyebrow="Explore a comunidade" title="Encontre sua conexão" text="Busque quem pode ajudar você no próximo passo." /><div className="mb-6 grid gap-3 rounded-xl border bg-card p-4 shadow-sm md:grid-cols-[1fr_auto_auto]"><div className="relative"><Search className="absolute left-4 top-1/2 size-5 -translate-y-1/2 text-muted-foreground" /><Input value={query} maxLength={80} onChange={e=>setQuery(e.target.value)} className="h-12 pl-12" placeholder="Nome, disciplina ou assunto..." /></div><select value={role} onChange={e=>setRole(e.target.value)} className="h-12 rounded-xl border bg-background px-4 text-sm font-bold"><option>Todos</option><option>Professor</option><option>Voluntário</option></select><Button variant="outline" className="h-12" onClick={()=>setFilters(v=>!v)}><SlidersHorizontal /> {filters?"Ocultar filtros":"Mais filtros"}</Button>{filters&&<div className="grid gap-3 border-t pt-4 md:col-span-3 md:grid-cols-2"><Field label="Avaliação mínima"><select value={rating} onChange={e=>setRating(Number(e.target.value))} className="h-11 rounded-xl border bg-background px-3"><option value="0">Qualquer nota</option><option value="4.85">4,85 ou mais</option><option value="4.9">4,90 ou mais</option></select></Field><Field label="Horário"><select value={period} onChange={e=>setPeriod(e.target.value)} className="h-11 rounded-xl border bg-background px-3"><option>Qualquer horário</option><option>Manhã</option><option>Tarde</option><option>Noite</option></select></Field><Button variant="ghost" className="md:col-span-2" onClick={()=>{setQuery("");setRole("Todos");setRating(0);setPeriod("Qualquer horário");}}>Limpar filtros</Button></div>}</div><div className="mb-4 flex items-center justify-between"><b>{filtered.length} conexões encontradas</b><span className="text-sm text-muted-foreground">{period} • melhor avaliação</span></div>{filtered.length?<div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{filtered.map(p=><InstructorCard key={p.name} {...p}/>)}</div>:<EmptyState icon={Search} title="Nenhuma conexão encontrada" text="Tente remover algum filtro ou buscar outra disciplina."/>}</div></AppShell>; }

export function RankingPage() { const [tab,setTab]=useState("Professores"); const ranked=instructors.filter(i=>i.role===(tab==="Professores"?"Professor":"Voluntário")); return <AppShell><div className="page-enter"><PageTitle eyebrow="Quem transforma, inspira" title="Ranking da comunidade" text="Reconhecemos consistência, qualidade e impacto em cada aula." /><div className="mb-6 rounded-xl bg-secondary p-4 text-sm text-secondary-foreground"><b>Pontuação justa:</b> média das avaliações ponderada pelo número de aulas e avaliações recebidas.</div><Tabs values={["Professores","Voluntários"]} value={tab} setValue={setTab} /><div className="mt-7 grid gap-4 lg:grid-cols-[1fr_320px]"><Card><CardContent className="divide-y p-0">{ranked.concat(ranked,ranked,ranked).slice(0,10).map((p,i)=><div key={p.name+i} className="flex items-center gap-4 p-4 sm:p-5"><div className={`grid size-9 place-items-center rounded-lg font-black ${i===0?"bg-warning text-warning-foreground":i===1?"bg-muted text-foreground":i===2?"bg-coral/20 text-coral":"text-muted-foreground"}`}>{i<3?<Medal className="size-5" />:i+1}</div><Avatar initials={p.initials} className={p.tone} /><div className="min-w-0 flex-1"><b className="block truncate">{p.name}</b><span className="text-xs text-muted-foreground">{p.subject} • {p.lessons+i*3} aulas</span></div><div className="text-right"><b className="flex items-center gap-1"><Star className="size-4 fill-warning text-warning" />{Math.max(4.6,p.rating-i*.02).toFixed(2)}</b><span className="text-[10px] text-muted-foreground">média</span></div></div>)}</CardContent></Card><aside><Card className="overflow-hidden"><div className="bridge-gradient p-6 text-primary-foreground"><Trophy className="mb-4 size-10" /><h3 className="text-2xl font-black">Impacto que cresce junto</h3><p className="mt-2 text-sm text-primary-foreground/80">Cada encontro fortalece toda a comunidade.</p></div><CardContent className="space-y-4 p-5">{[["2.847","aulas realizadas"],["1.206","alunos alcançados"],["96%","presenças confirmadas"]].map(x=><div key={x[1]} className="flex items-baseline justify-between"><b className="text-xl">{x[0]}</b><span className="text-xs text-muted-foreground">{x[1]}</span></div>)}</CardContent></Card></aside></div></div></AppShell>; }

export function ProfilePage() { const userName=useUserName(); const [mode,setMode]=useState("Ensinar"); const [editing,setEditing]=useState(false); const [name,setName]=useState(userName); const [city,setCity]=useState("São Paulo, SP"); const achievements: Array<[typeof Award,string]>=[[Award,"Mentor dedicado"],[HeartHandshake,"Impacto coletivo"],[Star,"Muito bem avaliado"]]; return <AppShell role="Voluntário"><div className="page-enter"><div className="relative mb-20 h-48 overflow-hidden rounded-2xl bridge-gradient"><div className="absolute inset-0 opacity-20 [background-image:radial-gradient(circle_at_20%_30%,var(--color-primary-foreground)_2px,transparent_2px)] [background-size:28px_28px]" /></div><div className="relative -mt-32 px-4 sm:px-8"><div className="flex flex-col gap-5 sm:flex-row sm:items-end"><Avatar initials="GJ" className="size-28 border-4 border-background bg-coral text-3xl text-coral-foreground shadow-xl" /><div className="mb-2 flex-1 text-primary-foreground sm:text-primary-foreground"><h1 className="text-3xl font-black">{name}</h1><p className="text-sm opacity-80">Voluntário • {city}</p></div><Button variant="outline" className="mb-2 bg-background" onClick={()=>setEditing(true)}><Settings /> Editar perfil</Button></div></div><div className="mt-7 grid gap-6 lg:grid-cols-[1fr_340px]"><div className="space-y-6"><Card><CardHeader><div className="flex flex-wrap items-center justify-between gap-3"><CardTitle>Meu perfil</CardTitle><TrustBadge role="Voluntário" /></div></CardHeader><CardContent><p className="leading-relaxed text-muted-foreground">Acredito que conhecimento compartilhado abre caminhos. Ensino programação para iniciantes e estou sempre buscando aprender algo novo com a comunidade.</p><div className="mt-6 grid grid-cols-3 gap-3 text-center">{[["4,9","avaliação"],["42","aulas dadas"],["36","alunos"]].map(x=><div key={x[1]} className="rounded-xl bg-muted p-4"><b className="block text-2xl">{x[0]}</b><span className="text-xs text-muted-foreground">{x[1]}</span></div>)}</div></CardContent></Card><Card><CardHeader><div className="flex items-center justify-between"><CardTitle>Minha jornada</CardTitle><Tabs values={["Ensinar","Aprender"]} value={mode} setValue={setMode} compact /></div></CardHeader><CardContent><div className="flex flex-wrap gap-2">{(mode==="Ensinar"?["Programação básica","Lógica","Ferramentas digitais"]:["Inglês","Design","Matemática financeira"]).map(x=><Badge key={x} variant="secondary" className="px-3 py-2">{x}</Badge>)}</div><p className="mt-4 text-sm text-muted-foreground">{mode==="Ensinar"?"Conhecimentos que compartilho como instrutor voluntário.":"Assuntos que quero aprender como aluno, sem precisar de outra conta."}</p></CardContent></Card></div><aside className="space-y-5"><Card><CardHeader><CardTitle>Próximos horários</CardTitle></CardHeader><CardContent className="space-y-3">{["Terça • 18:00–20:00","Quinta • 18:00–20:00","Sábado • 09:00–12:00"].map(x=><button key={x} className="flex w-full items-center gap-2 rounded-lg bg-muted p-3 text-left text-sm" onClick={()=>toast.info(`${x} selecionado.`)}><Clock3 className="size-4 text-primary" />{x}</button>)}</CardContent></Card><Card><CardHeader><CardTitle>Conquistas</CardTitle></CardHeader><CardContent className="flex gap-3">{achievements.map(([Icon,label])=><Button key={label} size="icon" variant="ghost" onClick={()=>toast.success(label)} aria-label={label}><Icon /></Button>)}</CardContent></Card></aside></div></div><Dialog open={editing} onOpenChange={setEditing}><DialogContent><DialogHeader><DialogTitle>Editar perfil</DialogTitle><DialogDescription>Atualize as informações exibidas à comunidade.</DialogDescription></DialogHeader><form className="space-y-4" onSubmit={e=>{e.preventDefault();setEditing(false);toast.success("Perfil atualizado!");}}><Field label="Nome"><Input value={name} onChange={e=>setName(e.target.value)} minLength={3} maxLength={100} required/></Field><Field label="Cidade"><Input value={city} onChange={e=>setCity(e.target.value)} minLength={2} maxLength={100} required/></Field><Field label="Sobre você"><Input defaultValue="Acredito que conhecimento compartilhado abre caminhos." maxLength={300}/></Field><Button className="w-full">Salvar alterações</Button></form></DialogContent></Dialog></AppShell>; }

export function UsersPage() { type ManagedUser={name:string;role:string;status:string;document:string}; const [status,setStatus]=useState("Todos"); const [query,setQuery]=useState(""); const [advanced,setAdvanced]=useState(false); const [users,setUsers]=useState<ManagedUser[]>([{name:"Ana Clara",role:"Professor",status:"Pendente",document:"Diploma em Letras"},{name:"Lucas Rocha",role:"Voluntário",status:"Pendente",document:"Ensino médio"},{name:"Camila Nunes",role:"Aluno",status:"Aprovado",document:"—"},{name:"Pedro Martins",role:"Professor",status:"Suspenso",document:"Lic. Matemática"}]); const update=(name:string,next:string)=>{setUsers(v=>v.map(u=>u.name===name?{...u,status:next}:u));toast.success(`${name}: status alterado para ${next}.`)}; const visible=users.filter(u=>(status==="Todos"||u.status===status)&&u.name.toLowerCase().includes(query.toLowerCase())); return <AppShell role="Admin"><div className="page-enter"><PageTitle eyebrow="Área administrativa" title="Gerenciar usuários" text="Valide cadastros e mantenha a comunidade segura." /><div className="mb-5 grid gap-4 sm:grid-cols-3"><Stat icon={ClipboardCheck} label="Aguardando análise" value={String(users.filter(u=>u.status==="Pendente").length)} helper="cadastros para revisar" tone="bg-warning/25 text-warning-foreground" /><Stat icon={UserCheck} label="Usuários ativos" value={String(users.filter(u=>u.status==="Aprovado").length)} helper="nesta demonstração" tone="bg-success/15 text-success" /><Stat icon={Users} label="Total de perfis" value={String(users.length)} helper="lista demonstrativa" /></div><Card><CardHeader><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><CardTitle>Todos os usuários</CardTitle><div className="flex gap-2"><select value={status} onChange={e=>setStatus(e.target.value)} className="h-10 rounded-lg border bg-background px-3 text-sm"><option>Todos</option><option>Pendente</option><option>Aprovado</option><option>Reprovado</option><option>Suspenso</option></select><Button variant="outline" size="icon" onClick={()=>setAdvanced(v=>!v)} aria-label="Filtros avançados"><Filter /></Button></div></div>{advanced&&<Input value={query} maxLength={80} onChange={e=>setQuery(e.target.value)} placeholder="Buscar pelo nome do usuário..."/>}</CardHeader><CardContent className="overflow-x-auto p-0"><table className="w-full min-w-[760px] text-left text-sm"><thead className="border-y bg-muted/60 text-xs uppercase text-muted-foreground"><tr><th className="p-4">Usuário</th><th>Perfil</th><th>Status</th><th>Documento</th><th className="pr-4 text-right">Ações</th></tr></thead><tbody className="divide-y">{visible.map((u,i)=><tr key={u.name}><td className="p-4"><div className="flex items-center gap-3"><Avatar initials={u.name.split(" ").map(x=>x[0]).join("")} /><div><b>{u.name}</b><small className="block text-muted-foreground">cadastro há {i+1} dias</small></div></div></td><td><Badge variant="secondary">{u.role}</Badge></td><td><Badge className={u.status==="Pendente"?"bg-warning text-warning-foreground":u.status==="Aprovado"?"bg-success text-success-foreground":"bg-destructive text-destructive-foreground"}>{u.status}</Badge></td><td>{u.document}</td><td className="pr-4"><div className="flex justify-end gap-1"><Dialog><DialogTrigger asChild><Button size="icon" variant="ghost" aria-label={`Ver documento de ${u.name}`}><Eye /></Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Documento de {u.name}</DialogTitle><DialogDescription>Arquivo enviado durante o cadastro.</DialogDescription></DialogHeader><div className="grid aspect-[4/3] place-items-center rounded-xl bg-muted"><div className="text-center"><BookOpen className="mx-auto mb-3 size-12 text-primary" /><b>{u.document}</b><p className="text-sm text-muted-foreground">documento-comprovante.pdf</p></div></div><div className="grid grid-cols-2 gap-3"><Button variant="outline" onClick={()=>update(u.name,"Reprovado")}><XCircle /> Reprovar</Button><Button onClick={()=>update(u.name,"Aprovado")}><Check /> Aprovar</Button></div></DialogContent></Dialog><Button size="icon" variant="ghost" aria-label={u.status==="Suspenso"?`Reativar ${u.name}`:`Suspender ${u.name}`} onClick={()=>update(u.name,u.status==="Suspenso"?"Aprovado":"Suspenso")}><Ban /></Button><Button size="icon" variant="ghost" aria-label={`Remover ${u.name}`} onClick={()=>{setUsers(v=>v.filter(x=>x.name!==u.name));toast.error("Conta removida da lista.");}}><Trash2 /></Button></div></td></tr>)}</tbody></table>{!visible.length&&<EmptyState icon={Users} title="Nenhum usuário encontrado" text="Ajuste os filtros para ver outros cadastros."/>}</CardContent></Card></div></AppShell>; }

function Tabs({ values,value,setValue,compact=false }:{values:string[];value:string;setValue:(v:string)=>void;compact?:boolean}) { return <div className={`inline-flex rounded-xl bg-muted p-1 ${compact?"":"w-full sm:w-auto"}`}>{values.map(v=><Button key={v} size="sm" variant={value===v?"default":"ghost"} className={compact?"":"flex-1 sm:flex-none"} onClick={()=>setValue(v)}>{v}</Button>)}</div>; }
function EmptyState({icon:Icon,title,text}:{icon:typeof Home;title:string;text:string}) { return <div className="rounded-xl border border-dashed bg-card px-6 py-16 text-center"><div className="mx-auto mb-4 grid size-14 place-items-center rounded-xl bg-secondary text-primary"><Icon /></div><h3 className="text-lg font-black">{title}</h3><p className="mx-auto mt-1 max-w-md text-sm text-muted-foreground">{text}</p></div>; }

function RoleBanner({ role }: { role: Role }) {
  const tone = role === "Admin" ? "bg-destructive/10 text-destructive" : role === "Professor" ? "bg-success/15 text-success" : role === "Voluntário" ? "bg-coral/15 text-coral" : "bg-secondary text-primary";
  return <div className="mb-6 flex flex-wrap items-center gap-2 rounded-xl border bg-card p-3 text-xs"><Badge className={`${tone} gap-1`}><ShieldCheck className="size-3" /> Nível de acesso: {role}</Badge>{permissions[role].map(p => <span key={p} className="rounded-full bg-muted px-2 py-1 font-semibold text-muted-foreground">{p}</span>)}</div>;
}
type NewLesson = { subject: string; title: string; when: string; teacher: string; status: string; topics: string[] };
function LessonAction({ onRequest, onCreated }: { onRequest: () => void; onCreated: (l: NewLesson) => void }) { const userName = useUserName();
  const [role] = useRole(); const [open, setOpen] = useState(false);
  if (role === "Admin") return <Button variant="outline" onClick={() => toast.info("Admin acompanha as aulas, mas não agenda.")}><Eye /> Somente visualização</Button>;
  if (role !== "Professor") return <Button onClick={onRequest}><CalendarDays /> Solicitar aula</Button>;
  const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); const title = String(f.get("title")).trim(); const when = String(f.get("when")); const topics = String(f.get("topics")).split(",").map(t => t.trim()).filter(Boolean);
    if (title.length < 3 || !when) { toast.error("Preencha título e data."); return; }
    onCreated({ subject: String(f.get("subject")), title, when: new Date(when).toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" }), teacher: userName, status: "Confirmada", topics: topics.length ? topics : ["Apresentação do tema"] }); setOpen(false); toast.success("Aula marcada! Os alunos serão avisados."); };
  return <><Button onClick={() => setOpen(true)}><CalendarDays /> Marcar aula</Button><Dialog open={open} onOpenChange={setOpen}><DialogContent><DialogHeader><DialogTitle>Marcar nova aula</DialogTitle><DialogDescription>Disponível apenas para professores com certificado validado.</DialogDescription></DialogHeader><form onSubmit={submit} className="grid gap-3"><Field label="Disciplina"><select name="subject" className="h-10 w-full rounded-md border bg-background px-3 text-sm">{["Matemática","Português","Inglês","Física","Biologia","Tecnologia"].map(x => <option key={x}>{x}</option>)}</select></Field><Field label="Título da aula"><Input name="title" maxLength={80} required placeholder="Ex.: Frações na prática" /></Field><Field label="Data e horário"><Input name="when" type="datetime-local" required /></Field><Field label="Temas (separados por vírgula)"><Input name="topics" maxLength={300} placeholder="Ex.: Conceito, Exemplos, Exercícios" /></Field><Field label="Vagas"><Input name="seats" type="number" min={1} max={100} defaultValue={20} /></Field><Button type="submit"><Check /> Confirmar aula</Button></form></DialogContent></Dialog></>;
}
type Post = { id: number; author: string; role: Role; initials: string; text: string; tag: string; likes: number; liked: boolean; comments: string[]; time: string };
const seedPosts: Post[] = [
  { id: 1, author: "Marina Souza", role: "Professor", initials: "MS", text: "Dica rápida: para achar o vértice da parábola use x = -b/2a. Salve esse post para a prova! 📐", tag: "Matemática", likes: 42, liked: false, comments: ["Ajudou muito, prof!"], time: "2h" },
  { id: 2, author: "Caio Mendes", role: "Voluntário", initials: "CM", text: "Montei um mini-guia de HTML em 5 passos. Quem quiser, comenta que eu mando o link na aula de sábado 💻", tag: "Tecnologia", likes: 31, liked: false, comments: [], time: "5h" },
  { id: 3, author: "Lívia Santos", role: "Professor", initials: "LS", text: "Na redação, a proposta de intervenção precisa de agente, ação, meio, finalidade e detalhamento. ✍️", tag: "Português", likes: 58, liked: false, comments: ["Anotado!", "Valeu!"], time: "1d" },
];
export function CommunityPage() { const userName = useUserName();
  const [role] = useRole(); const [posts, setPosts] = useState(seedPosts); const [text, setText] = useState(""); const [tag, setTag] = useState("Matemática"); const [filter, setFilter] = useState("Todos"); const [comment, setComment] = useState<Record<number, string>>({});
  const canPost = role === "Professor" || role === "Voluntário"; const canModerate = role === "Admin";
  const publish = () => { const t = text.trim(); if (t.length < 5) { toast.error("Escreva pelo menos 5 caracteres."); return; } setPosts(v => [{ id: Date.now(), author: userName, role, initials: initialsOf(userName), text: t.slice(0, 500), tag, likes: 0, liked: false, comments: [], time: "agora" }, ...v]); setText(""); toast.success("Conhecimento publicado! 🎉"); };
  const shown = posts.filter(p => filter === "Todos" || p.tag === filter);
  return <AppShell><div className="page-enter"><PageTitle eyebrow="Rede de conhecimento" title="Comunidade" text="Professores e voluntários compartilham o que sabem. Todos aprendem." />
  <div className="grid gap-6 xl:grid-cols-[1fr_320px]"><div className="space-y-4">
  {canPost ? <Card><CardContent className="p-5"><div className="flex gap-3"><Avatar initials={initialsOf(userName)} /><textarea value={text} onChange={e => setText(e.target.value)} maxLength={500} rows={3} placeholder="Compartilhe uma dica, resumo ou curiosidade..." className="w-full resize-none rounded-xl border bg-muted p-3 text-sm outline-none focus:ring-2 focus:ring-ring" /></div><div className="mt-3 flex flex-wrap items-center justify-between gap-2"><div className="flex items-center gap-2"><select value={tag} onChange={e => setTag(e.target.value)} className="h-9 rounded-md border bg-background px-2 text-sm">{["Matemática","Português","Inglês","Tecnologia","Ciências"].map(x => <option key={x}>{x}</option>)}</select><span className="text-xs text-muted-foreground">{text.length}/500</span></div><Button onClick={publish}><Sparkles /> Publicar</Button></div></CardContent></Card>
  : <Card><CardContent className="flex items-center gap-3 p-5 text-sm text-muted-foreground"><ShieldCheck className="text-primary" />{canModerate ? "Como Admin, você modera as publicações (pode remover conteúdos inadequados)." : "Alunos podem curtir, comentar e salvar. Publicar é exclusivo de Professores e Voluntários."}</CardContent></Card>}
  <Tabs values={["Todos","Matemática","Português","Tecnologia"]} value={filter} setValue={setFilter} />
  {shown.length === 0 && <EmptyState icon={MessageCircle} title="Nada por aqui ainda" text="Seja o primeiro a publicar sobre esse tema." />}
  {shown.map(p => <Card key={p.id} className="lift-card"><CardContent className="p-5"><div className="flex items-center gap-3"><Avatar initials={p.initials} /><div className="flex-1"><b className="text-sm">{p.author}</b><div className="flex items-center gap-2 text-xs text-muted-foreground">{(p.role === "Professor" || p.role === "Voluntário") && <TrustBadge role={p.role} />}• {p.time}</div></div><Badge variant="secondary">{p.tag}</Badge>{canModerate && <Button size="icon" variant="ghost" aria-label="Remover publicação" onClick={() => { setPosts(v => v.filter(x => x.id !== p.id)); toast.info("Publicação removida pela moderação."); }}><Trash2 /></Button>}</div><p className="mt-4 text-sm leading-relaxed">{p.text}</p><div className="mt-4 flex gap-2 border-t pt-3"><Button size="sm" variant={p.liked ? "default" : "ghost"} onClick={() => setPosts(v => v.map(x => x.id === p.id ? { ...x, liked: !x.liked, likes: x.likes + (x.liked ? -1 : 1) } : x))}><Star /> {p.likes}</Button><Button size="sm" variant="ghost" onClick={() => toast.success("Publicação salva nos seus favoritos.")}><BookMarked /> Salvar</Button><Button size="sm" variant="ghost" onClick={() => { navigator.clipboard?.writeText(p.text); toast.success("Texto copiado para compartilhar."); }}><ArrowRight /> Compartilhar</Button></div>{p.comments.map((c, i) => <p key={i} className="mt-2 rounded-lg bg-muted px-3 py-2 text-xs">{c}</p>)}<form className="mt-3 flex gap-2" onSubmit={e => { e.preventDefault(); const c = (comment[p.id] ?? "").trim(); if (!c) return; setPosts(v => v.map(x => x.id === p.id ? { ...x, comments: [...x.comments, c.slice(0, 200)] } : x)); setComment(m => ({ ...m, [p.id]: "" })); }}><Input value={comment[p.id] ?? ""} onChange={e => setComment(m => ({ ...m, [p.id]: e.target.value }))} maxLength={200} placeholder="Comentar..." className="h-9" /><Button size="sm" type="submit" variant="secondary">Enviar</Button></form></CardContent></Card>)}
  </div><aside className="space-y-4"><Card><CardHeader><CardTitle className="text-base">O que cada perfil pode fazer</CardTitle></CardHeader><CardContent className="space-y-3 text-xs">{(Object.keys(permissions) as Role[]).map(r => <div key={r} className={`rounded-lg p-3 ${r === role ? "bg-secondary ring-2 ring-primary" : "bg-muted"}`}><b className="text-sm">{r}</b><ul className="mt-1 list-disc pl-4 text-muted-foreground">{permissions[r].map(x => <li key={x}>{x}</li>)}</ul></div>)}</CardContent></Card></aside></div></div></AppShell>;
}
